  for (const d of allDates) {
    const state = getSessionState(course, d);
    const isLeave = state && LEAVE_STATUSES.has(state.className);
    if (d === dateYmd) {
      return isLeave ? null : num + 1;
    }
    if (!isLeave) num++;
  }
