          new_date: form.new_date,
          start_time: normalizeTo30Min(form.new_start),
          end_time: newEnd
        })
      }).catch(() => {});
    }
  } catch (_) {}
  showRescheduleModal.value = false;
  rescheduleCourse.value = null;
  alert('調課完成');
  loadCourses();
}

